#!/usr/bin/env bash
# Check RDP (20000+VMID) and SMB (10000+VMID) connectivity over IPv4 and IPv6 via nc.
# Paste this script on the target machine; set VMID / VMID_SMB / VMID_RDP and HOST_IPS below.
# Arrays match NeuraVPS scripts/get_on_server_vmids.py (running + firewall flags).
# That script prints VMID, VMID_RDP, VMID_SMB — reorder the two lines here if you paste verbatim.
#   VMID      — both rdpEnabled and sambaEnabled
#   VMID_SMB  — sambaEnabled only
#   VMID_RDP  — rdpEnabled only
# Ctrl+C is ignored during checks (INT is discarded for this script only).

trap '' INT

VMID=( 201 202 203 204 207 208 209 210 211 212 213 214 215 216 217 218 219 220 221 222 223 224 225 226 227 228 229 232 235 236 237 241 244 245 246 247 248 250 251 252 253 256 257 258 259 260 261 262 263 264 265 266 267 268 269 270 274 275 276 277 278 279 280 281 282 286 287 288 290 291 292 294 295 296 297 298 299 303 305 306 307 308 309 310 311 312 313 314 315 316 317 320 321 322 323 325 330 331 332 333 336 337 342 343 346 347 348 349 350 351 352 353 354 355 357 358 359 360 361 364 365 366 367 368 369 370 372 373 374 375 376 377 378 379 384 385 386 387 388 389 392 393 396 397 398 399 400 401 402 403 404 405 406 407 409 410 411 412 413 414 415 416 417 419 420 421 422 423 424 425 428 429 430 431 432 433 434 435 436 437 438 439 440 441 442 443 444 445 446 447 448 449 450 451 452 453 454 455 456 457 458 459 460 461 462 463 464 465 466 467 468 469 472 474 475 476 477 480 481 482 483 484 485 486 487 490 494 495 496 497 498 499 500 501 502 503 504 505 506 507 508 510 511 512 515 517 518 519 520 521 522 523 524 525 526 527 528 529 531 532 533 534 535 536 537 538 539 540 541 542 543 544 545 546 549 550 551 552 553 554 555 556 557 558 559 560 564 565 566 571 572 573 574 575 576 579 580 581 582 583 584 585 586 587 588 589 590 591 592 593 594 595 596 597 598 599 600 601 602 603 604 605 606 607 608 609 610 612 613 614 615 616 617 618 619 622 623 624 625 626 627 629 630 631 632 634 635 637 639 640 641 642 643 644 646 647 648 649 650 651 652 653 654 655 656 657 658 659 660 661 662 663 664 665 666 667 668 669 670 671 672 673 674 677 678 679 680 681 682 683 684 685 686 687 688 689 690 691 692 693 694 695 696 699 700 701 702 703 704 705 706 707 708 709 710 711 712 713 716 717 718 719 720 721 722 723 724 725 726 727 728 729 730 731 732 733 734 735 736 737 738 739 740 741 743 744 745 746 747 748 749 750 751 752 753 754 755 756 757 758 761 762 763 764 765 766 767 768 769 770 771 772 773 774 775 776 777 778 779 780 781 782 783 784 785 786 787 788 789 790 791 792 793 794 795 796 797 798 799 801 802 803 804 805 806 807 808 809 810 811 812 813 814 815 816 817 818 819 820 823 824 825 826 827 828 829 830 831 832 834 835 836 837 838 839 843 844 845 846 847 848 849 850 855 856 859 860 861 862 863 864 865 866 867 868 869 870 871 872 873 874 875 876 877 880 881 882 884 885 886 887 888 889 890 891 892 893 894 895 897 898 899 900 903 905 906 909 915 916 917 918 919 920 921 922 923 924 925 926 927 928 929 930 931 932 933 934 935 936 937 938 939 940 941 942 943 944 945 946 948 949 950 951 952 953 954 955 956 957 958 959 960 961 962 966 967 968 969 970 971 972 973 974 975 976 979 981 982 983 986 987 990 991 992 994 995 996 997 998 999 1000 1001 1002 1003 1004 1005 1006 1007 1008 1009 1010 1011 1012 1013 1014 1015 1016 1017 1018 1019 1020 1021 1022 1025 1026 1027 1028 1029 1030 1031 1032 1033 1034 1035 1036 1037 1038 1039 1040 1041 1042 1043 1044 1045 1046 1047 1048 1049 1050 1051 1052 1053 1054 1055 1056 1057 1058 1059 1060 1061 1062 1063 1064 1065 1066 1067 1068 1069 1070 1071 1072 1074 1075 1076 1077 1078 1079 1080 1081 1082 1083 1084 1085 1086 1087 1088 1089 1090 1091 1092 1093 1094 1095 1096 1097 1098 1099 1100 1101 1102 1103 1106 1107 1108 1109 1110 1111 1112 1113 1114 1115 1116 1117 1118 1119 1120 1121 1122 1125 1126 1127 1128 1129 1130 1131 1132 1133 1134 1135 1136 1137 1138 1139 1140 1141 1142 1143 1144 1147 1148 1149 1150 1151 1152 1153 1154 1155 1156 1157 1159 1160 1161 1162 1163 1164 1165 1166 1167 1168 1169 1171 1172 1173 1174 1175 1176 1177 1178 1179 1180 1181 1182 1183 1184 1190 1197 1198 1204 1216 1217 1234 1258 1264 1280 1286 1287 1299 1306 1311 1332 1337 1343 1344 1345 1349 1352 1358 1364 1379 1397 1402 1408 1410 1442 1452 1454 1536 1555 1582 1598 )
VMID_RDP=( )
VMID_SMB=( )

# Ingress IPs to probe (IPv4 and/or IPv6). Add as many entries as needed.
HOST_IPS=(
  "116.202.118.221"         # BASE 0 ECC
  "2a01:4f8:2b01:124::2"   # BASE 0 ECC
  "95.216.102.179"          # BASE 1 ECC
  "2a01:4f9:2a:2d56::2"    # BASE 1 ECC
  "94.130.3.118"            # FAILOVER FSN v4
  "2a01:4f8:fff2:95::2"    # FAILOVER FSN v6
  "77.42.49.79"             # FAILOVER HEL v4
  "2a01:4f9:fff1:5f::2"    # FAILOVER HEL v6
)
NC_TIMEOUT=3

# nc -zv -w 3 77.42.49.79 20201

failures=()

# bucket: label in logs; want_rdp / want_smb: 1 or 0
check_one_vmid() {
  local bucket=$1 vmid=$2 want_rdp=$3 want_smb=$4
  local port_rdp=$((20000 + vmid))
  local port_smb=$((10000 + vmid))
  local vmid_fails=()

  for host in "${HOST_IPS[@]}"; do
    if [[ "$want_rdp" -eq 1 ]]; then
      if ! nc -z -w "$NC_TIMEOUT" "$host" "$port_rdp" 2>/dev/null; then
        vmid_fails+=( "$host RDP ($port_rdp)" )
        failures+=( "$bucket $vmid: $host RDP ($port_rdp) FAIL" )
      fi
    fi
    if [[ "$want_smb" -eq 1 ]]; then
      if ! nc -z -w "$NC_TIMEOUT" "$host" "$port_smb" 2>/dev/null; then
        vmid_fails+=( "$host SMB ($port_smb)" )
        failures+=( "$bucket $vmid: $host SMB ($port_smb) FAIL" )
      fi
    fi
  done

  if [[ ${#vmid_fails[@]} -eq 0 ]]; then
    echo "$bucket $vmid: OK"
  else
    echo "$bucket $vmid: FAIL ($(IFS=,; echo "${vmid_fails[*]}"))"
  fi
}

for vmid in "${VMID[@]}"; do
  check_one_vmid VMID "$vmid" 1 1
done
for vmid in "${VMID_SMB[@]}"; do
  check_one_vmid VMID_SMB "$vmid" 0 1
done
for vmid in "${VMID_RDP[@]}"; do
  check_one_vmid VMID_RDP "$vmid" 1 0
done

echo ""
echo "--- Summary ---"
if [[ ${#failures[@]} -eq 0 ]]; then
  echo "All checks passed."
else
  echo "Failures:"
  printf '%s\n' "${failures[@]}"
fi
